    pRT->CreateSolidColorBrush(
        isDark ? D2D1::ColorF(0.24f, 0.26f, 0.30f, 0.90f) : D2D1::ColorF(0.78f, 0.80f, 0.85f, 0.90f),
        &m_pStickySepBrush);
    pRT->CreateSolidColorBrush(D2D1::ColorF(0.0f, 0.0f, 0.0f, isDark ? 0.28f : 0.10f), &m_pStickyShadowBrush);
